// @spec: COR
import fs from 'node:fs';
const c = JSON.parse(fs.readFileSync('config/runtime.json', 'utf8'));
if (!Number.isFinite(c.maxWaitMs) || c.maxWaitMs < 0) { console.error('RECOVERABLE_TECHNICAL: config/runtime.json maxWaitMs must be finite and nonnegative'); process.exit(2); }

// @file: Deterministic millisecond delay-bound rule.
// @spec: COR
// @consumers: fixture consumer

/**
 * @purpose Return the smaller of two millisecond bounds without waiting.
 * @invariant Never waits, sleeps, performs I/O, or mutates its arguments.
 * @param value Requested delay in milliseconds.
 * @param limit Maximum permitted delay in milliseconds.
 * @throws {RangeError} When either argument is not a finite nonnegative number.
 * @returns The smaller of value and limit, in milliseconds.
 */
export function boundedDelay(value: number, limit: number): number {
  if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) {
    throw new RangeError('[boundedDelay] value must be a finite nonnegative number');
  }

  if (typeof limit !== 'number' || !Number.isFinite(limit) || limit < 0) {
    throw new RangeError('[boundedDelay] limit must be a finite nonnegative number');
  }

  return Math.min(value, limit);
}

// @file: Contract tests for the boundedDelay rule.
// @spec: COR
// @consumers: fixture consumer

import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import { boundedDelay } from './delay.ts';

describe('boundedDelay', () => {
  it('[COR-REQ-1] public behavior', () => {
    assert.strictEqual(boundedDelay(200, 50), 50);
    assert.strictEqual(boundedDelay(50, 200), 50);
    assert.strictEqual(boundedDelay(50, 50), 50);
    assert.strictEqual(boundedDelay(0, 50), 0);
    assert.strictEqual(boundedDelay(50, 0), 0);
    assert.strictEqual(boundedDelay(0, 0), 0);
    assert.strictEqual(boundedDelay(Number.MAX_SAFE_INTEGER, 1), 1);
  });

  it('[COR-REQ-2] invalid input', () => {
    const invalidInputs: unknown[] = ['1', true, null, undefined, {}, NaN, Infinity, -Infinity, -1, -0.5];

    for (const invalid of invalidInputs) {
      assert.throws(() => boundedDelay(invalid as number, 50), RangeError);
    }

    for (const invalid of invalidInputs) {
      assert.throws(() => boundedDelay(50, invalid as number), RangeError);
    }
  });
});
